INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Immunology','Pathology','Innate Immunity','easy','mcq','Which complement pathway is activated directly by microbial surface polysaccharides without antibody?','["A. Classical pathway", "B. Lectin pathway", "C. Alternative pathway", "D. Terminal lytic pathway"]','C','The alternative pathway is activated spontaneously on microbial surfaces via low-level C3 hydrolysis without requiring antibody. The lectin pathway requires mannose-binding lectin binding to microbial carbohydrates. The classical pathway requires IgG or IgM antibody. The terminal pathway is downstream of all three.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Innate Immunity','medium','mcq','TLR4 recognises which pathogen-associated molecular pattern (PAMP)?','["A. Lipopolysaccharide (LPS)", "B. Flagellin", "C. Double-stranded RNA", "D. Unmethylated CpG DNA"]','A','TLR4 on the plasma membrane recognises lipopolysaccharide (endotoxin) from gram-negative bacteria. TLR5 recognises flagellin; TLR3 recognises dsRNA; TLR9 recognises unmethylated CpG DNA. TLR4 signals through MyD88 and TRIF adaptors to activate NF-kappaB and IRF3.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Innate Immunity','medium','mcq','Which cytokine produced during innate immunity induces fever by stimulating PGE2 synthesis in the hypothalamus?','["A. IL-10", "B. IL-12", "C. IFN-gamma", "D. IL-1 beta"]','D','IL-1 beta (and TNF) are the principal endogenous pyrogens; they stimulate hypothalamic COX-2-mediated PGE2 synthesis, raising the temperature set-point. IL-12 drives Th1 differentiation; IFN-gamma activates macrophages; IL-10 is anti-inflammatory.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Innate Immunity','hard','mcq','NK cells kill virus-infected cells by recognising the ABSENCE of which self-marker on the target cell?','["A. MHC class II", "B. MHC class I", "C. CD16 (FcgammaRIII)", "D. NKG2D ligand"]','B','NK inhibitory receptors (KIRs and NKG2A/CD94) recognise MHC class I (HLA-A, B, C). Viruses and tumours downregulate MHC I, removing this inhibitory signal and permitting NK killing (missing-self). CD16 mediates ADCC; NKG2D is an activating receptor; MHC II is not expressed on most nucleated cells.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Innate Immunity','easy','mcq','Which statement best describes a pathogen-associated molecular pattern (PAMP)?','["A. Conserved microbial structures essential for infectivity recognised by innate immune receptors", "B. Host-derived danger molecules released by necrotic cells", "C. Tumour neoantigens presented on MHC class I", "D. IgG Fc regions recognised by phagocyte Fc receptors"]','A','PAMPs are conserved microbial structures shared among pathogens and essential for survival — LPS, peptidoglycan, flagellin, dsRNA. They are recognised by pattern recognition receptors. Host danger signals are DAMPs. Fc recognition is opsonisation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Innate Immunity','medium','mcq','The NLRP3 inflammasome cleaves pro-caspase-1 when activated by urate crystals and ATP. What are the immediate downstream effectors of active caspase-1?','["A. Activated TNF-alpha", "B. Active IFN-alpha", "C. Active IL-12 and IFN-gamma", "D. Active IL-1 beta and IL-18"]','D','Active caspase-1 cleaves pro-IL-1beta and pro-IL-18 into mature secreted forms, driving fever and neutrophil recruitment. This underlies gout pathogenesis and autoinflammatory syndromes. TNF is processed by TACE (ADAM17); IL-12 processing is independent of caspase-1.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Innate Immunity','hard','mcq','TNF mediates hypotension in septic shock. Which specific molecular mechanism underlies TNF-induced vasodilation?','["A. Upregulation of angiotensin-converting enzyme in lung endothelium", "B. Induction of iNOS in vascular smooth muscle producing nitric oxide", "C. Direct cardiotoxicity via mitochondrial calcium overload", "D. Inhibition of aldosterone release from adrenal cortex"]','B','TNF and IL-1 induce iNOS in vascular smooth muscle and endothelium, producing large quantities of NO that cause widespread vasodilation and refractory hypotension of septic shock. This underlies the failure of peripheral vascular resistance in gram-negative bacteraemia.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Innate Immunity','medium','mcq','Mannose-binding lectin (MBL) activates complement via which pathway?','["A. Classical pathway requiring C1q binding to antibody", "B. Alternative pathway via Factor B and Factor D", "C. Lectin pathway via MASP-1 and MASP-2", "D. Properdin stabilisation pathway"]','C','MBL binds mannose residues on microbial surfaces and activates MASP-1 and MASP-2 which cleave C4 and C2, generating the C3 convertase. This is the lectin pathway. The classical pathway requires C1q-antibody binding; the alternative pathway is initiated by spontaneous C3 hydrolysis amplified by Factor B and D.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Innate Immunity','easy','mcq','Which complement fragment is the most potent anaphylatoxin and chemoattractant for neutrophils?','["A. C5a", "B. C4b (minor opsonin)", "C. C3b (principal opsonin)", "D. C1q (classical pathway initiator)"]','A','C5a is the most potent complement-derived anaphylatoxin, triggering mast cell and basophil degranulation, increasing vascular permeability, and powerfully recruiting neutrophils. C3b is the principal opsonin. C4b has minor opsonin function. C1q initiates the classical pathway.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Innate Immunity','hard','mcq','A patient with recurrent Neisseria meningitidis infections has intact opsonisation but absent bacteriolytic activity. Deficiency of which complement components most likely explains this?','["A. C3", "B. C4", "C. C5 through C9", "D. Factor B"]','C','Terminal complement components C5-C9 form the membrane attack complex (MAC), which lyses gram-negative bacteria including Neisseria species. Isolated C5-C9 deficiency predisposes specifically to Neisseria infections while opsonophagocytosis (C3b-dependent) remains intact. C3 deficiency causes broad susceptibility to encapsulated bacteria; Factor B is part of the alternative pathway.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - T cells','easy','mcq','CD4+ helper T cells recognise antigen presented on which MHC molecule?','["A. MHC class I on all nucleated cells", "B. MHC class II on professional antigen-presenting cells", "C. MHC class I on B lymphocytes only", "D. MHC class II on cytotoxic T cells"]','B','CD4+ T cells interact with peptide-MHC class II complexes. MHC II is constitutively expressed on professional APCs (dendritic cells, macrophages, B cells). CD8+ T cells recognise peptide-MHC class I. MHC II is not normally expressed on cytotoxic T cells. This MHC restriction underlies CD4/CD8 lineage commitment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - T cells','medium','mcq','Which T-helper subset produces IL-17 and IL-22 and defends against extracellular fungi and bacteria at mucosal surfaces?','["A. Th1", "B. Th2", "C. Th17", "D. Treg"]','C','Th17 cells differentiated by TGF-beta plus IL-6 (maintained by IL-23) produce IL-17A, IL-17F, and IL-22. IL-17 recruits neutrophils; IL-22 strengthens epithelial barriers. Th17 cells defend against Candida and extracellular bacteria at mucosae. Th1 secretes IFN-gamma; Th2 secretes IL-4/IL-5/IL-13; Tregs secrete IL-10/TGF-beta.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - T cells','medium','mcq','Which mechanism does a CD8+ CTL use to kill a target by directly injecting pore-forming proteins and proteases?','["A. Perforin-granzyme pathway", "B. Secretion of lymphotoxin (TNF-beta)", "C. Fas-FasL interaction triggering extrinsic apoptosis", "D. ADCC via CD16 on NK cells"]','A','CTLs release cytotoxic granules containing perforin (polymerises to form pores) and granzymes (serine proteases that activate caspase-3 and caspase-9, inducing apoptosis). Fas-FasL triggers extrinsic apoptosis independently. Lymphotoxin has weak cytotoxic activity. ADCC is mediated by NK cells via CD16.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - T cells','easy','mcq','Which transcription factor is the master regulator of regulatory T cell (Treg) development and function?','["A. T-bet (Th1 master regulator)", "B. GATA-3 (Th2 master regulator)", "C. RORgamma-t (Th17 master regulator)", "D. FoxP3"]','D','FoxP3 is the lineage-defining transcription factor for CD4+CD25+ Tregs. Mutations in FoxP3 cause IPEX syndrome, a fatal multi-organ autoimmune disorder. T-bet drives Th1; GATA-3 drives Th2; RORgamma-t drives Th17. These master regulators are mutually cross-inhibitory.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - T cells','hard','mcq','Cross-presentation loads exogenous antigen onto MHC class I to prime CD8+ T cells. Which cell type is primarily responsible?','["A. Plasmacytoid dendritic cells (pDC) specialising in type I IFN", "B. Conventional type 1 dendritic cells (cDC1) expressing XCR1", "C. Mast cells", "D. Neutrophils"]','B','Conventional type 1 DCs (cDC1, expressing XCR1 and BDCA-3 in humans) are the specialised cross-presenting APCs. They reroute exogenous antigens from dying tumour cells into the MHC class I pathway to prime CD8+ T cells, critical for anti-tumour immunity. pDCs specialise in type I interferon production.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - T cells','medium','mcq','Which cytokine drives naive CD4+ T cell differentiation into the Th1 lineage to combat intracellular pathogens?','["A. IL-12", "B. IL-4", "C. IL-6 combined with TGF-beta", "D. IL-10"]','A','IL-12, produced by macrophages and DCs responding to intracellular pathogens, signals through STAT4 and upregulates T-bet, driving Th1 differentiation. IL-4 plus IL-2 drives Th2 (GATA-3); IL-6 plus TGF-beta drives Th17 (RORgamma-t); IL-10 is anti-inflammatory and does not drive lineage commitment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - T cells','hard','mcq','Which molecule expressed by medullary thymic epithelial cells enables presentation of peripheral self-antigens for negative selection of autoreactive T cells?','["A. RAG1/RAG2 V(D)J recombinase", "B. CD28 co-stimulatory molecule", "C. AIRE (autoimmune regulator)", "D. ZAP-70 tyrosine kinase"]','C','AIRE drives ectopic transcription of peripheral self-antigens (insulin, thyroglobulin, retinal S-antigen) in mTECs. These peptides are presented on MHC to developing T cells; strongly self-reactive T cells are deleted (negative selection). AIRE loss-of-function causes APS-1/APECED with hypoparathyroidism, Addison disease, and mucocutaneous candidiasis.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - T cells','medium','mcq','Which co-stimulatory interaction is blocked by abatacept (CTLA-4-Ig) to prevent T cell activation in autoimmune arthritis and graft rejection?','["A. CD40 binding CD40L on T cells", "B. LFA-1 binding ICAM-1 on endothelium", "C. PD-1 binding PD-L1 on APCs", "D. CD28 on T cells binding B7 (CD80/CD86) on APCs"]','D','Signal 2 for complete T cell activation requires CD28-B7 engagement. Abatacept (CTLA-4-Ig) presents CTLA-4 as a higher-affinity decoy for B7, competitively blocking CD28 engagement. Without co-stimulation, antigen-specific T cells become anergic. Abatacept is approved for RA and used in some transplant protocols.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - T cells','easy','mcq','T cell receptor gene rearrangement in the thymus is carried out by which enzyme?','["A. Terminal deoxynucleotidyl transferase (TdT) alone", "B. RAG1/RAG2 V(D)J recombinase", "C. Activation-induced cytidine deaminase (AID)", "D. DNA-PKcs alone"]','B','RAG1 and RAG2 constitute the V(D)J recombinase that introduces double-strand breaks at RSS sequences flanking V, D, J segments to enable TCR and BCR rearrangement. TdT adds N-nucleotides at junctions increasing junctional diversity. AID mediates somatic hypermutation and class-switch recombination in germinal centre B cells only.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - T cells','hard','mcq','After liver transplantation a patient develops CD8+ T cell hepatitis. In direct allorecognition, how do recipient CD8+ CTLs identify graft cells?','["A. Via intact donor MHC class I molecules on graft parenchymal cells", "B. Via recipient MHC class I presenting processed donor peptides", "C. Via NKG2D recognising stress ligands on graft cells", "D. Via donor MHC class II on graft dendritic cells"]','A','In direct allorecognition, recipient CD8+ CTLs recognise intact donor MHC class I molecules bearing donor peptides on the surface of graft parenchymal cells. This bypasses the need for recipient APC processing and is the dominant pathway in early acute cellular rejection. Indirect allorecognition involves recipient APCs processing donor antigens presented on self-MHC.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - B cells','easy','mcq','What process introduces point mutations into Ig variable regions in germinal centre B cells to generate higher-affinity antibodies?','["A. V(D)J recombination in bone marrow", "B. Somatic hypermutation (SHM)", "C. Class-switch recombination", "D. Receptor editing"]','B','Somatic hypermutation, catalysed by AID in germinal centre B cells, introduces point mutations into Ig variable regions. B cells with higher-affinity BCRs are selectively rescued from apoptosis (affinity maturation). V(D)J recombination occurs earlier in bone marrow during primary B cell development.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - B cells','medium','mcq','Which cytokine drives B cell class switching from IgM to IgG1 and IgG3 in humans?','["A. IL-4", "B. IL-5", "C. TGF-beta", "D. IFN-gamma"]','D','IFN-gamma from Th1 cells drives class switching to IgG1 and IgG3 in humans, effective at opsonisation and complement activation. IL-4 drives IgG4 and IgE switching; TGF-beta drives IgA switching; IL-5 promotes eosinophil survival. All switching requires CD40-CD40L co-stimulation and AID.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - B cells','medium','mcq','Which surface markers identify long-lived plasma cells and distinguish them from memory B cells?','["A. CD38-high, CD138 (syndecan-1)-positive, absent surface BCR", "B. CD19-high, CD20-high, surface BCR-positive", "C. CD27-low, surface IgM BCR-positive", "D. CD21-high, CD40-positive"]','A','Long-lived plasma cells downregulate CD19, CD20, and surface BCR but express high CD38 and CD138 (syndecan-1). They home to bone marrow niches and secrete antibody for decades. Memory B cells retain surface BCR, CD19, CD20, and CD27 (high). Targeting CD38 with daratumumab underlies myeloma therapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - B cells','easy','mcq','T-independent bacterial polysaccharide antigens stimulate B cells directly without T cell help. The antibody response is primarily which isotype?','["A. IgG4", "B. IgA secretory dimer", "C. IgM", "D. IgE"]','C','T-independent antigens cross-link multiple BCRs, triggering a rapid IgM response. Without T cell help (CD40-CD40L, cytokines), germinal centre formation, affinity maturation, and class switching do not occur. This is why unconjugated polysaccharide vaccines are poorly immunogenic in children under 2 years.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - B cells','hard','mcq','During central B cell tolerance in the bone marrow, autoreactive B cells may avoid deletion via receptor editing. What does receptor editing involve?','["A. Reactivation of RAG1/RAG2 to rearrange a new immunoglobulin light chain", "B. Deletion of the entire immunoglobulin heavy chain locus", "C. AID-mediated somatic hypermutation of the autoreactive BCR", "D. FoxP3-dependent conversion into a regulatory B cell"]','A','Receptor editing reactivates RAG1/RAG2 in autoreactive immature B cells, enabling secondary rearrangement of kappa or lambda light chain gene segments to produce a non-autoreactive BCR. If editing fails after multiple attempts, the cell undergoes clonal deletion. AID is involved in SHM and CSR, not receptor editing.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - B cells','medium','mcq','How do follicular dendritic cells (FDCs) in germinal centres present antigen to B cells, distinct from classical MHC-dependent presentation?','["A. FDCs present peptides on MHC class II to B cell receptor-like structures", "B. FDCs cross-present exogenous antigens on MHC class I", "C. FDCs trap intact antigen-antibody-complement complexes on their surface via Fc and complement receptors", "D. FDCs transfer antigen to B cells via gap junctions"]','C','FDCs capture and retain intact antigen as immune complexes (antigen-antibody with complement C3d) using Fc receptors and complement receptors CR1/CR2. Germinal centre B cells sample these complexes via their surface BCR. FDCs are non-haematopoietic stromal cells that do not process antigen or express MHC II.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - B cells','hard','mcq','A patient has monoclonal IgM that agglutinates red blood cells at temperatures below 30 degrees C (cold agglutinin disease). Which cell lineage produces this monoclonal IgM?','["A. Bone marrow plasma cells from IgM myeloma", "B. Memory B cells in the spleen", "C. Germinal centre centroblasts undergoing somatic hypermutation", "D. Lymphoplasmacytic cells carrying the MYD88 L265P somatic mutation"]','D','Cold agglutinin disease is caused by monoclonal IgM (binding I/i antigen on RBCs at cold temperatures) produced by lymphoplasmacytic cells, typically in Waldenstrom macroglobulinaemia where MYD88 L265P is present in over 90% of cases. These cells secrete IgM without class switching.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - B cells','easy','mcq','Which immunoglobulin isotype predominates in mucosal secretions including saliva, breast milk, and intestinal fluid?','["A. IgG (dominant serum isotype)", "B. IgM (pentameric first-response isotype)", "C. IgA (secretory dimer)", "D. IgE (allergy and helminth isotype)"]','C','Secretory IgA (sIgA) is a dimeric IgA joined by J chain and secretory component. It is the principal antibody at mucosal surfaces preventing pathogen adherence (immune exclusion). sIgA resists proteolysis in the gut. IgG is the dominant serum antibody and crosses the placenta; IgM is the first antibody produced in a primary response.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - B cells','medium','mcq','IL-4 from Th2 cells drives B cell class switching to IgE. Which transcription factor activated downstream of IL-4 receptor signalling is required for germline epsilon transcription?','["A. STAT6", "B. T-bet", "C. RORgamma-t", "D. NF-kappaB alone"]','A','IL-4 signals through JAK1/JAK3 to phosphorylate STAT6, which upregulates germline epsilon transcription and cooperates with AID to enable class switching to IgE. STAT6 also drives GATA-3 expression. T-bet cooperates with IFN-gamma/STAT1 to drive IgG switching; RORgamma-t is the Th17 master factor.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Adaptive Immunity - B cells','medium','mcq','Which feature of memory B cells best explains the faster, higher-titre secondary antibody response upon re-exposure to antigen?','["A. Higher surface IgM density than naive B cells", "B. Lower activation threshold with high-affinity class-switched BCRs from the primary germinal centre reaction", "C. Greater MHC class II density for more efficient T cell help", "D. Constitutive low-level IgG secretion without further antigen stimulation"]','B','Memory B cells carry somatically mutated, affinity-matured, class-switched BCRs (IgG, IgA, or IgE) from the primary germinal centre reaction. These high-affinity receptors have a lower activation threshold, enabling rapid plasma cell differentiation upon re-exposure. This is the basis of the faster, higher-titre secondary immune response exploited by vaccination.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type I & II Hypersensitivity','easy','mcq','In type I immediate hypersensitivity, which cell types bear surface IgE via FcepsilonRI and release histamine upon allergen cross-linking?','["A. Mast cells (tissue) and basophils (blood)", "B. Neutrophils and eosinophils", "C. Plasma cells and naive B cells", "D. NK cells and macrophages"]','A','Mast cells in tissues and basophils in blood express high-affinity FcepsilonRI receptors binding IgE. Cross-linking by multivalent allergen triggers degranulation releasing histamine, heparin, tryptase, prostaglandins, and leukotrienes. This is the primary mechanism of anaphylaxis, allergic asthma, and allergic rhinitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type I & II Hypersensitivity','medium','mcq','Which mast cell mediators cause both bronchoconstriction and vasodilation in systemic anaphylaxis?','["A. IL-4 and IL-13", "B. Prostaglandin I2 (prostacyclin)", "C. Histamine and cysteinyl leukotrienes (LTC4 and LTD4)", "D. TNF-alpha and IL-6"]','C','Histamine (pre-formed, immediate) binds H1 receptors causing bronchoconstriction and vasodilation. Cysteinyl leukotrienes LTC4 and LTD4 (from 5-lipoxygenase/arachidonic acid) are more potent and longer-acting bronchoconstrictors. Together these mediate the acute bronchospasm and hypotension of anaphylaxis. Leukotriene receptor antagonists (montelukast) target LTC4/LTD4.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type I & II Hypersensitivity','medium','mcq','Autoimmune haemolytic anaemia (AIHA) is caused by antibodies against red blood cell antigens. Which hypersensitivity type does AIHA represent?','["A. Type I (IgE-mediated immediate hypersensitivity)", "B. Type III (immune complex-mediated disease)", "C. Type IV (T cell-mediated delayed hypersensitivity)", "D. Type II (antibody-mediated cytotoxic hypersensitivity)"]','D','AIHA is type II hypersensitivity: IgG or IgM antibodies against erythrocyte antigens lead to complement activation, opsonisation with C3b, and phagocytosis by splenic macrophages (extravascular haemolysis) or MAC-mediated intravascular haemolysis. Detected by direct Coombs test. Type I involves IgE; type III involves immune complex deposition; type IV is T cell-mediated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type I & II Hypersensitivity','hard','mcq','In myasthenia gravis, anti-AChR antibodies cause weakness by three type II mechanisms. Beyond complement-mediated end-plate damage, which mechanism specifically reduces functional AChR number?','["A. Antibody crosslinking of AChRs inducing receptor internalisation and lysosomal degradation (antigenic modulation)", "B. Opsonisation and phagocytosis of the neuromuscular junction by macrophages", "C. CD8+ CTL-mediated apoptosis of postsynaptic muscle membrane", "D. NK cell ADCC against motor end plates"]','A','Anti-AChR IgG antibodies cause weakness through: (1) blocking acetylcholine binding; (2) crosslinking adjacent AChRs, triggering internalisation and lysosomal degradation (antigenic modulation), reducing receptor density; and (3) complement activation causing end-plate ultrastructural damage. Antigenic modulation specifically reduces the number of functional receptors.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type I & II Hypersensitivity','easy','mcq','Graves disease is caused by antibodies that stimulate the TSH receptor, resulting in hyperthyroidism without elevated TSH. Which hypersensitivity type does this represent?','["A. Type I (IgE/mast cell-mediated)", "B. Type III (immune complex deposition)", "C. Type II (receptor-stimulating antibody-mediated)", "D. Type IV (T cell-mediated granulomatous)"]','C','Graves disease is type II hypersensitivity where anti-TSHR IgG (thyroid-stimulating immunoglobulins) act as receptor agonists, continuously stimulating thyroid hormone synthesis, producing diffuse goitre and hyperthyroidism. AIHA and myasthenia gravis (also type II) involve receptor blockade or cytotoxicity rather than receptor stimulation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type I & II Hypersensitivity','medium','mcq','Pemphigus vulgaris involves IgG antibodies against desmoglein-3. What is the primary pathological consequence in the epidermis?','["A. Subepidermal blistering via complement deposition at the basement membrane zone", "B. T cell-mediated eosinophilic spongiosis in the dermis", "C. Neutrophilic abscess formation within epidermal layers", "D. Intraepidermal acantholysis with suprabasal blister formation due to loss of keratinocyte-keratinocyte adhesion"]','D','Pemphigus vulgaris is type II hypersensitivity: anti-desmoglein-3 IgG disrupts desmosomal adhesion, causing acantholysis (cell separation) and suprabasal intraepidermal blistering. Tzanck smear shows acantholytic (tombstone) cells. Compare with bullous pemphigoid (anti-BP180/BP230) causing subepidermal blistering without acantholysis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type I & II Hypersensitivity','hard','mcq','The late-phase reaction in type I hypersensitivity occurs 4-8 hours after the immediate reaction. Which cell type is the principal mediator?','["A. Mast cells undergoing secondary degranulation", "B. Eosinophils recruited by IL-5, eotaxin, and LTB4", "C. Plasma cells locally secreting IgE in bronchial mucosa", "D. CD8+ cytotoxic T cells recognising allergen-MHC class I"]','B','The late-phase reaction is dominated by eosinophil recruitment driven by mast cell-derived IL-5, eotaxin (CCL11), and LTB4. Eosinophils release MBP, ECP, and LTC4/LTD4, sustaining inflammation and causing airway remodelling. This is the cellular basis of chronic asthmatic inflammation and the rationale for anti-IL-5 therapy (mepolizumab, benralizumab).','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type I & II Hypersensitivity','medium','mcq','Which clinical test confirms IgE-mediated sensitisation to a specific allergen?','["A. Direct Coombs (direct antiglobulin) test", "B. Skin prick test or serum-specific IgE measurement (ImmunoCAP)", "C. Schirmer tear test for lacrimal gland function", "D. Patch test read at 48-72 hours for contact allergens"]','B','The skin prick test introduces allergen intradermally; a wheal-and-flare reaction within 15-20 minutes (IgE-triggered mast cell degranulation) confirms sensitisation. Serum-specific IgE (ImmunoCAP/RAST) directly quantifies allergen-specific IgE. Direct Coombs detects antibody on erythrocytes (type II AIHA). Patch test at 48-72 hours evaluates type IV contact hypersensitivity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type I & II Hypersensitivity','easy','mcq','Haemolytic disease of the newborn due to Rh incompatibility is caused by maternal antibodies crossing the placenta. Which immunoglobulin isotype is responsible?','["A. IgM (large pentameric molecule)", "B. IgA (mucosal isotype)", "C. IgG", "D. IgE (allergic isotype)"]','C','IgG is the only antibody isotype that crosses the placenta, actively transported by FcRn on placental syncytiotrophoblasts. Maternal IgG anti-D antibodies (from sensitisation in a prior Rh+ pregnancy) cross into fetal circulation and bind fetal Rh+ erythrocytes causing haemolysis. Prevention: anti-D immunoglobulin (RhoGAM) within 72 hours of delivery.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type I & II Hypersensitivity','hard','mcq','Goodpasture syndrome shows linear IgG deposition along glomerular and alveolar basement membranes. What is the specific molecular target?','["A. The NC1 domain of the alpha-3 chain of type IV collagen", "B. Type I collagen in the mesangial matrix", "C. Laminin beta-2 chain of the GBM", "D. Desmoglein-3 expressed by glomerular podocytes"]','A','Goodpasture syndrome is caused by IgG autoantibodies against the NC1 domain of the alpha-3 chain of type IV collagen, concentrated in glomerular and pulmonary alveolar basement membranes. Complement activation causes crescentic glomerulonephritis and pulmonary haemorrhage. Linear immunofluorescence staining distinguishes it from granular immune complex nephritis.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type III & IV Hypersensitivity','easy','mcq','SLE produces glomerulonephritis primarily via which hypersensitivity mechanism?','["A. Type I - IgE/mast cell degranulation in glomeruli", "B. Type II - anti-dsDNA antibodies directly lysing glomerular cells", "C. Type III - immune complex deposition activating complement in glomeruli", "D. Type IV - CD4+ T cell granulomatous inflammation of glomeruli"]','C','SLE pathology is predominantly type III: nucleosome-anti-dsDNA and anti-Smith immune complexes deposit in glomeruli, activate complement (C3a/C5a), and recruit neutrophils, causing lupus nephritis. Immunofluorescence shows full-house granular staining (IgG, IgM, IgA, C3, C1q). The WHO/ISN classification grades lupus nephritis by extent of immune complex injury.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type III & IV Hypersensitivity','medium','mcq','Serum sickness occurring 7-10 days after horse anti-thymocyte globulin (ATG) is caused by which sequence of events?','["A. ATG triggers IgE production causing immediate mast cell degranulation and urticaria", "B. IgG antibodies form immune complexes with ATG depositing in vessels and activating complement causing vasculitis", "C. ATG activates Th1 cells forming granulomas around small vessels", "D. ATG directly cross-links B cells without T cell help causing glomerulonephritis"]','B','Serum sickness is the classical type III model: 7-10 days after exposure to foreign protein, the host mounts IgG antibody response. Immune complexes deposit in vessel walls, joints, and kidneys, activate complement, and recruit neutrophils causing vasculitis, arthritis, and glomerulonephritis. Clinical features: fever, urticaria, lymphadenopathy, and arthralgias.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type III & IV Hypersensitivity','medium','mcq','The Arthus reaction is local type III hypersensitivity. What prerequisite is required before intradermal antigen injection produces the reaction?','["A. Pre-sensitised antigen-specific CD4+ T cells", "B. C1q deficiency allowing immune complexes to persist", "C. Pre-existing circulating IgG antibodies against the injected antigen", "D. Pre-existing IgE antibodies against the injected antigen"]','C','The Arthus reaction requires pre-formed circulating IgG antibodies. Intradermal antigen forms immune complexes with IgG in situ, activating complement and recruiting neutrophils, causing localised oedema, haemorrhage, and necrosis within 4-8 hours. This differs from DTH (type IV) which requires pre-sensitised T cells and peaks at 48-72 hours.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type III & IV Hypersensitivity','easy','mcq','The Mantoux tuberculin skin test is read at 48-72 hours because it depends on which hypersensitivity mechanism?','["A. Type I - immediate IgE-triggered histamine release", "B. Type II - antibody-dependent complement-mediated cytotoxicity", "C. Type III - immune complex vasculitis", "D. Type IV - delayed-type hypersensitivity mediated by memory CD4+ Th1 cells"]','D','The Mantoux test is the prototype type IV DTH: intradermal PPD is presented by local APCs to memory CD4+ Th1 cells, which secrete IFN-gamma, activating macrophages and causing induration (>= 10 mm positive) peaking at 48-72 hours. The firmness reflects mononuclear cell infiltration and fibrin deposition, not just vascular leakage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type III & IV Hypersensitivity','hard','mcq','Contact dermatitis to nickel is type IV hypersensitivity. Which effector mechanism primarily causes keratinocyte damage?','["A. CD4+ Th1 cell secretion of IFN-gamma activating macrophages (classical DTH)", "B. NK cell ADCC against hapten-coated keratinocytes", "C. Local immune complex deposition activating complement in skin", "D. CD8+ T cell-mediated cytotoxicity of hapten-modified keratinocytes expressing modified MHC class I"]','D','Contact hypersensitivity to haptens (nickel, DNCB, urushiol) involves sensitisation by hapten-protein conjugates presented by DCs, then effector-phase CD8+ CTLs recognising hapten-modified peptides on keratinocyte MHC class I, killing keratinocytes via perforin/granzyme. This CD8+ T cell-driven type IV reaction differs from classical CD4+-mediated granulomatous DTH seen in tuberculosis.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type III & IV Hypersensitivity','medium','mcq','Granuloma formation in pulmonary tuberculosis represents which hypersensitivity type?','["A. Type I", "B. Type II", "C. Type III", "D. Type IV"]','D','Tuberculoid granuloma formation is type IV cell-mediated hypersensitivity. Mycobacterial antigens are presented by macrophages to CD4+ Th1 cells, which secrete IFN-gamma, activating macrophages that differentiate into epithelioid histiocytes and Langhans giant cells. TNF from macrophages maintains granuloma integrity and compartmentalises but does not eliminate the infection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type III & IV Hypersensitivity','hard','mcq','Acute cellular allograft rejection involving lymphocytic infiltration destroying graft parenchyma represents which hypersensitivity type?','["A. Type II - donor-specific alloantibodies", "B. Type III - immune complex vasculitis", "C. Type IV - T cell-mediated delayed hypersensitivity", "D. Type I - IgE-mediated mast cell activation in graft"]','C','Acute cellular rejection is type IV hypersensitivity: host CD4+ Th1 cells secrete IFN-gamma activating macrophages (interstitial inflammation), and CD8+ CTLs directly kill graft parenchymal cells (tubulitis in kidney). Banff classification grades tubulitis and intimal arteritis. Calcineurin inhibitors prevent acute rejection by blocking T cell IL-2 production.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type III & IV Hypersensitivity','medium','mcq','On renal biopsy immunofluorescence, which staining pattern distinguishes type III immune complex GN from type II anti-GBM disease?','["A. Linear IgG along GBM indicates immune complex disease", "B. Granular (lumpy-bumpy) C3 and IgG indicates immune complex disease; linear IgG indicates anti-GBM disease", "C. Absence of complement indicates type III", "D. Mesangial IgA alone indicates anti-GBM disease"]','B','Immune complex GN (type III) shows granular lumpy-bumpy deposits of IgG, IgM, C3, and/or C1q by immunofluorescence, reflecting trapping of circulating complexes at irregular sites in the GBM and mesangium. Anti-GBM disease (Goodpasture, type II) shows smooth linear IgG along the entire GBM, reflecting uniform binding to the alpha-3(IV)NC1 epitope. This distinction guides treatment (plasma exchange for anti-GBM).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type III & IV Hypersensitivity','easy','mcq','Which vasculitis is caused by IgA immune complex deposition and presents with purpura, arthralgia, and glomerulonephritis in children after a respiratory infection?','["A. IgA vasculitis (Henoch-Schonlein purpura)", "B. Systemic lupus erythematosus", "C. Polyarteritis nodosa", "D. Granulomatosis with polyangiitis (formerly Wegener)"]','A','IgA vasculitis (HSP) is the most common systemic vasculitis in children, characterised by IgA1-dominant immune complex deposition in small vessels of skin, joints, gut, and kidneys. It classically follows streptococcal or viral URTI. The renal lesion is histologically identical to IgA nephropathy. It is a type III hypersensitivity disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Type III & IV Hypersensitivity','hard','mcq','Why do type III immune complexes preferentially deposit in renal glomeruli and synovial joints?','["A. High hydrostatic pressure and active filtration concentrate immune complexes at these anatomical sites", "B. These tissues express uniquely high FcgammaRI density for immune complex capture", "C. These tissues lack complement regulatory proteins (CD55, CD59)", "D. Antigen is locally produced within glomeruli and synovium"]','A','Immune complex deposition is favoured at sites of high hydrostatic pressure, turbulence, and active ultrafiltration - the glomerular capillaries and synovial microvasculature. Intermediate-sized complexes formed in moderate antigen excess are most pathogenic: they escape phagocytosis in the bloodstream but become trapped in vessel walls at high-pressure filtration sites.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Autoimmune Diseases','easy','mcq','Which antibody is most specific for SLE and whose titre correlates with lupus nephritis activity?','["A. Anti-histone (drug-induced lupus)", "B. Anti-Ro/SSA (neonatal lupus, Sjogren)", "C. Anti-double-stranded DNA (anti-dsDNA)", "D. Anti-cyclic citrullinated peptide (anti-CCP, rheumatoid arthritis)"]','C','Anti-dsDNA antibodies have >95% specificity for SLE and titre correlates with disease activity, particularly lupus nephritis flares. Monitoring anti-dsDNA guides treatment decisions. Anti-Smith has highest specificity (>99%) but is present in only ~25% of patients. Anti-Ro/SSA is elevated in neonatal lupus and Sjogren syndrome; anti-CCP is specific for rheumatoid arthritis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Autoimmune Diseases','medium','mcq','Which process in the thymic medulla eliminates T cells that strongly recognise self-antigens, preventing autoimmunity?','["A. Clonal anergy from TCR engagement without CD28 co-stimulation", "B. Negative selection (clonal deletion) where strongly self-reactive T cells undergo apoptosis", "C. Receptor editing to replace the autoreactive TCR alpha or beta chain", "D. FoxP3-dependent conversion into thymic regulatory T cells"]','B','Negative selection in the thymic medulla: thymocytes receiving strong TCR signals from self-peptide-MHC activate pro-apoptotic cascades (Bim, Nur77) and are clonally deleted. AIRE in mTECs enables presentation of peripheral self-antigens. Clonal anergy and Treg suppression are peripheral tolerance mechanisms; receptor editing applies to B cells.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Autoimmune Diseases','medium','mcq','Rheumatoid arthritis is associated with rheumatoid factor (RF). What is RF?','["A. IgM antibody directed against the Fc portion of IgG", "B. IgG antibody directed against the Fc portion of IgM", "C. IgE antibody directed against citrullinated vimentin", "D. IgA antibody directed against type II collagen in articular cartilage"]','A','Rheumatoid factor (RF) is most commonly IgM directed against the Fc region of IgG. IgM-RF forms immune complexes in synovial fluid activating complement, contributing to joint inflammation in RA. RF has low specificity (also in Sjogren, cryoglobulinaemia, SBE, hepatitis C). Anti-CCP antibodies are more specific for RA and predict erosive disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Autoimmune Diseases','hard','mcq','In rheumatic fever following group A streptococcal pharyngitis, cross-reactive antibodies cause cardiac valve damage via which molecular mechanism?','["A. Immune complex deposition of streptococcal antigens in cardiac valve leaflets", "B. Direct invasion of cardiac myocytes by group A Streptococcus", "C. Streptococcal superantigen-driven polyclonal T cell activation targeting cardiac tissue", "D. Molecular mimicry where anti-streptococcal M protein antibodies cross-react with cardiac myosin and sarcolemmal proteins"]','D','Molecular mimicry underlies rheumatic fever cardiac damage: streptococcal M protein shares epitopes with cardiac myosin, tropomyosin, and sarcolemmal proteins. Anti-streptococcal antibodies cross-react with heart valve proteins, activating complement and causing valvular inflammation. This explains why pharyngitis (but not skin impetigo) causes rheumatic fever, and forms the basis for penicillin prophylaxis.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Autoimmune Diseases','easy','mcq','Hashimoto thyroiditis is the most common cause of hypothyroidism in iodine-sufficient countries. Which autoantibodies are characteristically elevated?','["A. Thyroid-stimulating immunoglobulins (TSI) against TSH receptor", "B. Anti-double-stranded DNA antibodies", "C. Anti-thyroid peroxidase (anti-TPO) and anti-thyroglobulin antibodies", "D. Anti-cyclic citrullinated peptide antibodies"]','C','Hashimoto thyroiditis is characterised by high-titre anti-TPO (anti-microsomal) and anti-thyroglobulin antibodies. Histology shows diffuse lymphocytic infiltration with germinal centres, Hurthle (Askanazy) cell metaplasia, and progressive fibrosis. Anti-TPO is positive in >90% of cases. TSI (stimulating anti-TSHR antibodies) are the hallmark of Graves disease, causing hyperthyroidism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Autoimmune Diseases','medium','mcq','Goodpasture syndrome is strongly associated with which HLA allele that presents the alpha-3(IV)NC1 peptide to autoreactive CD4+ T cells?','["A. HLA-DR3 (DRB1*0301)", "B. HLA-DR2 (DRB1*1501)", "C. HLA-B27", "D. HLA-DR4 (DRB1*0401)"]','B','Goodpasture syndrome has its strongest HLA association with HLA-DRB1*1501 (DR2 serotype). This allele presents a cryptic alpha-3(IV)NC1 peptide to autoreactive CD4+ T cells providing help to anti-GBM IgG-producing B cells. HLA-B27 is associated with ankylosing spondylitis; HLA-DR3 with SLE and Sjogren; HLA-DR4 with rheumatoid arthritis and type 1 diabetes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Autoimmune Diseases','hard','mcq','The anti-Smith (anti-Sm) antibody in SLE is directed against which specific antigen?','["A. Histones H2A and H2B complexed with DNA in nucleosomes", "B. Double-stranded DNA in the nucleus", "C. Protein components of small nuclear ribonucleoproteins (snRNPs)", "D. Phospholipid-beta-2-glycoprotein I complexes on cell membranes"]','C','Anti-Sm antibodies target the core protein components (B/B'''', D1, D2, D3, E, F, G) of snRNPs - the RNA-protein complexes involved in pre-mRNA splicing. Anti-Sm is the most specific antibody for SLE (>99% specificity) but present in only approximately 25% of patients. Anti-dsDNA is more sensitive (~70%) and both together define SLE immunologically.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Autoimmune Diseases','medium','mcq','Which of the following is NOT a mechanism of peripheral immunological tolerance?','["A. Positive selection of T cells in the thymic cortex", "B. Clonal anergy from signal 1 (TCR) without signal 2 (CD28) co-stimulation", "C. Regulatory T cell suppression via IL-10, TGF-beta, and CTLA-4", "D. Activation-induced cell death (AICD) via Fas-FasL apoptosis after repeated stimulation"]','A','Positive selection in the thymic cortex - where CD4+CD8+ thymocytes with TCRs capable of recognising self-MHC survive - is a central tolerance developmental step ensuring MHC restriction, not a peripheral tolerance mechanism. The three principal peripheral tolerance mechanisms are: (1) clonal anergy (signal 1 alone); (2) Treg-mediated suppression; and (3) AICD via Fas-FasL (repeated stimulation of self-reactive T cells triggers apoptosis).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Autoimmune Diseases','hard','mcq','Sjogren syndrome destroys exocrine glands causing dry eyes and dry mouth. What is the primary mechanism of acinar cell destruction?','["A. IgE-mediated mast cell degranulation in glandular parenchyma", "B. IgA immune complex deposition causing complement-mediated lysis of ductal cells", "C. Membrane attack complex lysis of acinar cells via activated complement", "D. CD4+ Th1 and CD8+ T cell infiltration inducing acinar cell apoptosis via perforin/granzyme and Fas-FasL"]','D','Sjogren syndrome is primarily T cell-mediated (type IV): focal lymphocytic sialadenitis with CD4+ Th1 and CD8+ T cells infiltrating glands, secreting IFN-gamma and BAFF, killing acinar cells via perforin/granzyme and Fas-FasL. Anti-Ro (SSA) and anti-La (SSB) are diagnostically important but are not the direct mediators of acinar destruction.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Autoimmune Diseases','easy','mcq','Which factor best explains why SLE predominantly affects women of childbearing age at a 9:1 female-to-male ratio?','["A. Oestrogen lowers the activation threshold of autoreactive B cells and upregulates TLR7 promoting autoantibody production", "B. Testosterone upregulates TLR7 expression on B cells", "C. Progesterone inhibits FoxP3+ regulatory T cell development", "D. Double X chromosomes double gene dosage of complement genes causing complement deficiency"]','A','Oestrogen promotes B cell hyperactivity, enhances survival of autoreactive B cells, upregulates TLR7 (sensing ssRNA from apoptotic nucleosomal material), and lowers the activation threshold for self-reactive B cells. These effects collectively drive the strong female predominance of SLE. X chromosome-linked TLR7 gene and epigenetic dysregulation of X-inactivation may provide additional contributions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Primary Immunodeficiencies','easy','mcq','X-linked agammaglobulinaemia (Bruton disease) results from mutation in which gene, arresting B cell maturation at the pre-B cell stage?','["A. RAG1 (recombination activating gene 1)", "B. BTK (Bruton tyrosine kinase)", "C. ADA (adenosine deaminase)", "D. CD40L (CD154, CD40 ligand)"]','B','Bruton XLA is caused by loss-of-function mutations in BTK (Xq21.33-q22), encoding Bruton tyrosine kinase required for pre-B cell receptor signalling. Without BTK, B cell development arrests at the pro-B/pre-B transition. Boys present after 6 months with absent circulating B cells, undetectable serum immunoglobulins, and recurrent infections with encapsulated bacteria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Primary Immunodeficiencies','medium','mcq','DiGeorge syndrome results from chromosome 22q11.2 microdeletion. What is the primary immunological defect?','["A. Absence of bone marrow haematopoietic stem cell niche", "B. Failure of lymph node development (aplastic lymphadenopathy)", "C. Thymic aplasia or hypoplasia causing T cell maturation failure", "D. Congenital asplenia causing absent opsonophagocytic immunity"]','C','DiGeorge syndrome results from failure of the third and fourth pharyngeal pouches to form, causing thymic aplasia or hypoplasia with severely impaired T cell maturation. B cells develop normally but immunoglobulin levels fall due to absent T cell help. Associated features: conotruncal cardiac defects, hypocalcaemia (absent parathyroids), cleft palate, and facial dysmorphia (CATCH-22 mnemonic).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Primary Immunodeficiencies','medium','mcq','ADA deficiency causes SCID by accumulating a metabolite toxic to lymphocytes. Which metabolite is primarily responsible?','["A. Hypoxanthine", "B. Uric acid", "C. Homocysteine", "D. Deoxyadenosine and dATP"]','D','ADA deficiency causes accumulation of deoxyadenosine and its triphosphate form (dATP). dATP inhibits ribonucleotide reductase and induces p53-dependent apoptosis, selectively destroying lymphocytes (especially T cells), producing T-B-NK- SCID. Treatment: HSCT (curative), pegademase enzyme replacement, or gene therapy. Uric acid accumulates in Lesch-Nyhan syndrome (HGPRT deficiency).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Primary Immunodeficiencies','easy','mcq','Selective IgA deficiency is the most common primary immunodeficiency. What is the most clinically dangerous risk requiring special precaution during blood transfusion?','["A. Severe combined immunodeficiency from birth", "B. Absent lymph nodes and tonsils from birth", "C. Anaphylaxis to blood products due to IgE or IgG anti-IgA antibodies in the recipient", "D. Opportunistic infections with Pneumocystis jirovecii"]','C','Approximately 30% of symptomatic IgA-deficient patients produce IgE or IgG anti-IgA antibodies. When they receive blood transfusions containing IgA, anaphylaxis can occur. IgA-deficient patients requiring blood products should receive IgA-depleted blood or washed red blood cells. Beyond transfusion risk, symptomatic patients have recurrent sinopulmonary infections and giardiasis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Primary Immunodeficiencies','hard','mcq','CVID differs from Bruton XLA in that B cells are present in normal numbers but cannot differentiate into plasma cells. Which complication unique to CVID requires long-term surveillance?','["A. Thymic carcinoma from chronic thymic stimulation", "B. Splenic rupture from IgM paraprotein deposition", "C. Primary sclerosing cholangitis from bile duct IgA deficiency", "D. B cell lymphoma, autoimmune cytopenias, and non-caseating granulomatous disease"]','D','CVID (both sexes, presents 2nd-3rd decade) has increased risks not seen in XLA: B cell non-Hodgkin lymphoma (10-20 fold increased), autoimmune cytopenias (ITP, AIHA), inflammatory bowel-like enteropathy, and non-caseating granulomatous disease affecting lungs, liver, and spleen. XLA (males only, absent B cells) rarely develops these complications; CVID requires regular lymphoma and autoimmunity surveillance.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Primary Immunodeficiencies','medium','mcq','Wiskott-Aldrich syndrome (WAS) is an X-linked disorder caused by WASp gene mutations. Which triad defines the classic phenotype?','["A. Eczema, thrombocytopenia with small platelets (microthrombocytopenia), and progressive combined immunodeficiency", "B. Cerebellar ataxia, oculocutaneous telangiectasia, and selective IgA deficiency", "C. Partial oculocutaneous albinism, recurrent pyogenic infections, and giant lysosomal granules", "D. Lymphopenia, reduced IgM, and preserved IgG with normal B cell counts"]','A','Wiskott-Aldrich syndrome presents with eczema, microthrombocytopenia (small platelets, low count), and progressive immunodeficiency. WASp regulates actin cytoskeleton polymerisation in haematopoietic cells; deficiency impairs lymphocyte migration, immune synapse formation, and platelet production. Patients are susceptible to encapsulated bacteria, Pneumocystis, herpesviruses, and EBV-driven lymphoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Primary Immunodeficiencies','hard','mcq','Chediak-Higashi syndrome shows giant lysosomal granules in neutrophils and NK cells. What is the specific molecular defect?','["A. CYBB (gp91phox) mutation causing absent NADPH oxidase activity in neutrophils", "B. ITGB2 (CD18) mutation causing failure of neutrophil adhesion to endothelium", "C. LYST gene mutation causing defective lysosomal vesicle fusion and membrane trafficking", "D. RAG2 mutation causing defective V(D)J recombination and absent lymphocytes"]','C','Chediak-Higashi syndrome is caused by autosomal recessive mutations in LYST (lysosomal trafficking regulator, 1q42). Defective LYST protein causes abnormal vesicle fusion producing giant lysosomes in all granule-containing cells. Consequences: impaired neutrophil bactericidal activity, absent NK cytotoxicity, partial oculocutaneous albinism, peripheral neuropathy, and a lymphoma-like EBV-driven accelerated phase.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Primary Immunodeficiencies','easy','mcq','A 2-year-old boy has recurrent Staphylococcus aureus and Aspergillus fumigatus infections. The NBT test shows absent colour change. Which diagnosis does this confirm?','["A. X-linked agammaglobulinaemia (Bruton)", "B. Chronic granulomatous disease (CGD)", "C. DiGeorge syndrome (thymic aplasia)", "D. Severe combined immunodeficiency (SCID)"]','B','Chronic granulomatous disease is caused by mutations in NADPH oxidase (most commonly CYBB encoding gp91phox on the X chromosome). Neutrophils phagocytose normally but cannot generate reactive oxygen species. The NBT test: absent colour change confirms the oxidative burst defect. CGD patients are specifically susceptible to catalase-positive organisms: Staphylococcus aureus, Aspergillus, Serratia marcescens, and Burkholderia cepacia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Primary Immunodeficiencies','medium','mcq','Leukocyte adhesion deficiency (LAD) type I presents with recurrent bacterial infections, elevated blood neutrophil count, and absent pus. Which molecule is deficient?','["A. CXCR4 chemokine receptor for SDF-1/CXCL12", "B. P-selectin glycoprotein ligand-1 (PSGL-1)", "C. Myeloperoxidase in azurophil granules", "D. CD18 (beta-2 integrin ITGB2) which pairs with CD11a (LFA-1) and CD11b (Mac-1)"]','D','LAD type I is caused by autosomal recessive mutations in ITGB2 (CD18). Without CD18, leukocytes cannot form beta-2 integrin-ICAM-1 interaction required for firm endothelial adhesion and transendothelial migration. Clinical hallmarks: delayed umbilical cord separation (>3 weeks), absent pus despite marked peripheral neutrophilia, and progressive bacterial infections.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Primary Immunodeficiencies','hard','mcq','Ataxia-telangiectasia (AT) is caused by ATM kinase mutations. Why are AT patients at markedly increased risk of T cell leukaemia and lymphoma?','["A. ATM repairs DNA double-strand breaks during V(D)J recombination; its loss permits oncogenic chromosomal translocations involving TCR loci to persist", "B. ATM mutations cause constitutive NF-kappaB activation driving lymphocyte proliferation", "C. ATM deficiency prevents apoptosis of autoreactive lymphocytes escaping negative selection", "D. ATM is specifically required for IgE class-switch recombination only"]','A','ATM kinase coordinates the cellular response to DNA double-strand breaks. During V(D)J recombination, programmed DSBs are introduced by RAG1/RAG2. In AT, defective ATM-mediated DSB repair allows chromosomal translocations to occur and persist, particularly involving TCR alpha (14q11) and TCR beta (7q34) loci, predisposing to T cell leukaemia and lymphoma. AT patients also have cerebellar ataxia, telangiectasias, and radiosensitivity.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Secondary Immunodeficiencies','easy','mcq','HIV infects CD4+ T cells by binding CD4 with which viral envelope glycoprotein, followed by co-receptor engagement causing membrane fusion?','["A. gp41 (transmembrane fusion protein)", "B. gp120 (surface glycoprotein)", "C. p24 (capsid antigen)", "D. Integrase enzyme"]','B','HIV gp120 binds CD4 on T cells, macrophages, and dendritic cells, causing conformational changes that expose the gp120 V3 loop for co-receptor (CCR5 or CXCR4) binding. gp41 then mediates membrane fusion. R5-tropic strains (using CCR5) predominate early; X4-tropic strains (using CXCR4) emerge later. CCR5 delta-32 homozygotes lack CCR5 and are nearly completely resistant to HIV-1 infection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Secondary Immunodeficiencies','medium','mcq','At what CD4+ T cell count threshold should co-trimoxazole PCP prophylaxis be started in an HIV-positive patient?','["A. Below 500 cells per microlitre", "B. Below 350 cells per microlitre", "C. Below 200 cells per microlitre", "D. Below 100 cells per microlitre"]','C','PCP (Pneumocystis jirovecii pneumonia) risk rises significantly when CD4 count falls below 200 cells per microlitre, which also constitutes the CD4-based definition of AIDS. Co-trimoxazole (TMP-SMX) is the drug of choice for primary and secondary PCP prophylaxis. At CD4 below 100, toxoplasma prophylaxis is added; at below 50, MAC prophylaxis with azithromycin is considered.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Secondary Immunodeficiencies','medium','mcq','Post-splenectomy patients are susceptible to overwhelming sepsis (OPSI). Which organisms are primarily responsible and what prophylaxis is given?','["A. Intracellular organisms (Listeria, Salmonella) requiring rifampicin prophylaxis", "B. Candida and Aspergillus requiring fluconazole prophylaxis", "C. Enterobacteriaceae (E. coli, Klebsiella) requiring ciprofloxacin prophylaxis", "D. Encapsulated bacteria (S. pneumoniae, H. influenzae type b, N. meningitidis) requiring vaccination plus penicillin V prophylaxis"]','D','The spleen is essential for opsonisation and antibody responses against encapsulated bacteria whose polysaccharide capsules resist direct phagocytosis. Without a spleen, these organisms cause rapid fatal sepsis (OPSI). Standard management: vaccination against S. pneumoniae (PCV13/PPSV23), H. influenzae type b, and N. meningitidis (ACWY/B), plus lifelong penicillin V prophylaxis, especially important in children.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Secondary Immunodeficiencies','hard','mcq','Glucocorticoids exert anti-inflammatory effects primarily through which genomic mechanism?','["A. Transrepression of NF-kappaB and AP-1 transcription factors and upregulation of IkappaB-alpha", "B. Blocking histamine release from mast cell granule fusion with plasma membrane", "C. Activating complement regulatory proteins (CD55, CD59) on host cell surfaces", "D. Inducing FoxP3 expression in naive T cells to generate peripherally induced Tregs"]','A','Glucocorticoid-receptor complexes translocate to the nucleus and inhibit NF-kappaB (by binding p65, preventing DNA binding) and AP-1, reducing transcription of pro-inflammatory cytokines (TNF, IL-1, IL-6, IL-12), enzymes (COX-2, iNOS), and adhesion molecules. GCs also upregulate IkappaB-alpha (NF-kappaB inhibitor) and lipocortin-1 (annexin-1, inhibiting phospholipase A2), reducing arachidonic acid availability for prostaglandin and leukotriene synthesis.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Secondary Immunodeficiencies','easy','mcq','Cyclophosphamide is used as an immunosuppressant in SLE, vasculitis, and organ transplantation. What is its principal mechanism?','["A. Calcineurin inhibition blocking IL-2 transcription", "B. De novo purine synthesis inhibition via IMPDH blockade", "C. DNA alkylation with interstrand cross-links causing selective killing of rapidly proliferating lymphocytes", "D. Anti-CD20 B cell depletion via complement-mediated lysis"]','C','Cyclophosphamide is activated by hepatic CYP enzymes to phosphoramide mustard, which alkylates DNA at guanine N7, forming interstrand cross-links that block replication, selectively killing rapidly dividing activated lymphocytes. This causes profound lymphopenia (B and T cell lineages). Haemorrhagic cystitis from acrolein is prevented by mesna and hydration.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Secondary Immunodeficiencies','medium','mcq','An HIV patient with CD4 count of 40 per microlitre develops multiple ring-enhancing brain lesions with oedema on MRI. Which diagnosis is most likely?','["A. CMV encephalitis (periventricular lesions)", "B. Cryptococcal meningoencephalitis", "C. Cerebral toxoplasmosis", "D. Progressive multifocal leukoencephalopathy (PML)"]','C','Cerebral toxoplasmosis (Toxoplasma gondii reactivation) presents in AIDS at CD4 below 100 as multiple ring-enhancing lesions in basal ganglia or grey-white junction with surrounding oedema on MRI. Treatment: pyrimethamine plus sulfadiazine plus folinic acid. CMV causes periventricular enhancement; cryptococcal disease causes meningitis without ring-enhancement; PML causes confluent non-enhancing white matter lesions (JC virus).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Secondary Immunodeficiencies','hard','mcq','Which mechanism beyond direct viral cytopathic effect contributes to progressive CD4+ T cell depletion in HIV infection?','["A. Bystander apoptosis of uninfected CD4+ cells via upregulated Fas-FasL signalling during chronic immune activation", "B. Direct NK cell killing of CD4+ cells via missing-self recognition", "C. Anti-CD4 autoantibodies from HIV-driven B cell hyperactivation", "D. Glucocorticoid excess from HIV-associated adrenal insufficiency"]','A','HIV depletes CD4+ T cells through multiple mechanisms: (1) Direct viral killing; (2) Bystander apoptosis - chronic immune activation upregulates Fas (CD95) on uninfected CD4+ T cells, making them susceptible to FasL-mediated apoptosis; (3) CTL killing of HIV-infected cells; (4) Pyroptosis of abortively infected resting CD4+ T cells via caspase-1. Chronic immune activation is a dominant driver of progressive CD4 depletion.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Secondary Immunodeficiencies','medium','mcq','An HIV patient with CD4 count 60 per microlitre has fever, night sweats, weight loss, and raised alkaline phosphatase. Blood culture grows acid-fast bacilli. Which organism is most likely?','["A. Mycobacterium tuberculosis", "B. Nocardia asteroides", "C. Histoplasma capsulatum", "D. Mycobacterium avium complex (MAC)"]','D','MAC (M. avium and M. intracellulare) causes disseminated infection in AIDS patients with CD4 below 50 per microlitre. Features: high fever, night sweats, weight loss, hepatosplenomegaly, and elevated alkaline phosphatase. MAC grows from blood cultures on acid-fast stain (critical diagnostic feature). M. tuberculosis reactivates at higher CD4 counts (below 200). Histoplasma is restricted to endemic areas and is not acid-fast.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Secondary Immunodeficiencies','hard','mcq','Mycophenolate mofetil (MMF) is used in transplant immunosuppression and lupus nephritis. What is its selective mechanism of action?','["A. IMPDH inhibition blocking de novo guanosine nucleotide synthesis, selectively suppressing lymphocyte proliferation", "B. Calcineurin inhibition reducing IL-2 production", "C. DNA alkylation preventing lymphocyte division", "D. mTORC1 inhibition blocking G1-to-S phase progression"]','A','Mycophenolic acid (active form of MMF) reversibly inhibits IMPDH, the rate-limiting enzyme of de novo guanosine nucleotide synthesis. Lymphocytes depend exclusively on the de novo pathway and lack sufficient salvage pathway capacity, making them selectively sensitive. Result: selective inhibition of lymphocyte DNA synthesis and proliferation. Calcineurin inhibition is tacrolimus/ciclosporin; mTOR inhibition is sirolimus.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Secondary Immunodeficiencies','easy','mcq','Which is the most common worldwide cause of secondary immunodeficiency characterised by thymic atrophy and impaired T cell function?','["A. HIV infection", "B. Protein-energy malnutrition", "C. Multiple myeloma with hypogammaglobulinaemia", "D. Chronic high-dose corticosteroid therapy"]','B','Protein-energy malnutrition (marasmus and kwashiorkor) is the most prevalent cause of secondary immunodeficiency globally. PEM causes thymic involution, impaired T cell maturation and function, reduced complement synthesis, impaired phagocyte function, and reduced secretory IgA. Children with PEM are highly susceptible to measles, tuberculosis, and enteric infections. HIV dominates in high-income countries but PEM affects hundreds of millions worldwide.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Transplant Immunology','easy','mcq','Hyperacute rejection of a kidney transplant occurs within minutes of revascularisation. What is the causative mechanism?','["A. CD8+ CTL killing of graft endothelial cells via direct allorecognition", "B. Pre-formed donor-specific antibodies binding graft endothelium activating complement and coagulation", "C. NK cell ADCC of graft endothelial cells via CD16", "D. CD4+ Th1 macrophage activation causing microvascular ischaemia"]','B','Hyperacute rejection is caused by pre-formed recipient antibodies (anti-HLA class I or anti-ABO) present at transplantation. They bind donor endothelial antigens within minutes, activating complement (C3a/C5a, MAC) and coagulation, causing diffuse intravascular thrombosis and ischaemic graft necrosis. Prevention: ABO compatibility and negative complement-dependent cytotoxicity crossmatch before transplantation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Transplant Immunology','medium','mcq','Tacrolimus and ciclosporin both prevent acute allograft rejection. What is their shared mechanism of action?','["A. mTOR complex 1 inhibition blocking S-phase entry", "B. CD28-B7 co-stimulation blockade preventing T cell priming", "C. Calcineurin phosphatase inhibition preventing NFAT dephosphorylation and IL-2 gene transcription", "D. Anti-lymphocyte antibodies depleting graft-reactive T cells"]','C','Both drugs form drug-immunophilin complexes (tacrolimus-FKBP12 and ciclosporin-cyclophilin A) that inhibit calcineurin phosphatase. Calcineurin normally dephosphorylates NFAT, enabling IL-2 gene transcription. Without IL-2, T cells cannot undergo clonal expansion and acute rejection is prevented. Both drugs are nephrotoxic. Sirolimus inhibits mTOR; abatacept blocks CD28-B7.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Transplant Immunology','medium','mcq','Chronic kidney allograft rejection occurring years post-transplantation is characterised by which hallmark histological feature?','["A. Neutrophilic glomerulitis with intracapillary neutrophils", "B. Acute tubular necrosis with epithelial flattening", "C. Non-caseating granulomatous interstitial nephritis", "D. Transplant glomerulopathy (double-contoured GBM) and fibrous intimal thickening of arteries"]','D','Chronic rejection is characterised on the Banff classification by transplant glomerulopathy (GBM duplication on silver stain), fibrous intimal thickening of graft arteries, interstitial fibrosis and tubular atrophy (IFTA), and peritubular capillary basement membrane multilayering. It results from cumulative antibody-mediated (DSA, C4d+) and T cell-mediated injury over years, leading to progressive graft function loss.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Transplant Immunology','hard','mcq','Which HLA locus is most critical to match in allogeneic HSCT to minimise acute GVHD risk?','["A. HLA-DRB1 (class II)", "B. HLA-A, HLA-B, and HLA-C (classical class I)", "C. HLA-E and HLA-G (non-classical HLA)", "D. MICA (MHC class I chain-related protein A)"]','A','Among all HLA loci, HLA-DRB1 mismatch has the greatest impact on acute GVHD severity and transplant-related mortality in matched unrelated donor HSCT. Standard 10/10 allele-level matching includes HLA-A, B, C (class I, 6 alleles) and HLA-DRB1 and HLA-DQB1 (class II, 4 alleles). A single HLA-DRB1 mismatch significantly increases GVHD risk more than mismatches at other loci.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Transplant Immunology','easy','mcq','Which organs are the principal targets of acute graft-versus-host disease (GVHD) after allogeneic HSCT?','["A. Liver, skin, and gastrointestinal tract", "B. Lungs, kidneys, and spleen", "C. Brain, peripheral nerves, and cranial nerves", "D. Heart muscle and endocrine pancreas"]','A','Acute GVHD (within 100 days of HSCT) affects the liver (cholestatic jaundice, elevated bilirubin and alkaline phosphatase), skin (diffuse maculopapular rash progressing to erythroderma), and gastrointestinal tract (profuse watery or bloody diarrhoea, abdominal cramping, ileus). These organs express high levels of recipient alloantigens on parenchymal and epithelial cells, making them targets of donor T cells.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Transplant Immunology','medium','mcq','In the indirect allorecognition pathway, how do recipient T cells recognise donor alloantigens?','["A. Recipient T cells directly engage intact donor MHC class I on graft parenchymal cells", "B. Recipient NK cells bind donor alloantibody-coated endothelial cells via CD16", "C. Recipient APCs internalise and present donor-derived peptides on self-MHC class II to recipient CD4+ T cells", "D. Donor MHC molecules are transferred intact to recipient dendritic cells by trogocytosis"]','C','In indirect allorecognition, donor MHC molecules shed from the graft are taken up, processed, and presented as allopeptides on self-MHC class II by recipient APCs to recipient CD4+ T cells. This pathway dominates in chronic rejection. Direct allorecognition (intact donor MHC recognised directly by recipient T cells) dominates in early acute rejection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Transplant Immunology','hard','mcq','The graft-versus-leukaemia (GVL) effect after allogeneic HSCT is therapeutically important for AML and CML. Which donor immune cells primarily mediate GVL?','["A. Donor FoxP3+ regulatory T cells suppressing residual leukaemic cells", "B. Donor B cells secreting anti-leukaemia antibodies", "C. Donor macrophages performing ADCP of leukaemic blasts", "D. Donor CD8+ CTLs and NK cells recognising and killing residual host leukaemic blasts"]','D','GVL is mediated by donor CD8+ CTLs recognising minor histocompatibility antigens on host haematopoietic cells and by donor NK cells killing leukaemic blasts lacking adequate self-HLA (missing-self). GVL is inseparably linked to GVHD since both are mediated by alloreactive donor T cells; T cell depletion of the graft eliminates acute GVHD but abolishes GVL, increasing relapse rates in AML and CML.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Transplant Immunology','medium','mcq','Sirolimus (rapamycin) is used in transplant regimens as an alternative to calcineurin inhibitors. What is its mechanism of action?','["A. Calcineurin phosphatase inhibition reducing IL-2 production", "B. CD28-B7 co-stimulation blockade", "C. mTORC1 inhibition blocking IL-2-driven cell cycle progression from G1 to S phase", "D. IMPDH inhibition blocking guanosine nucleotide synthesis"]','C','Sirolimus binds FKBP12, but the sirolimus-FKBP12 complex inhibits mTOR complex 1 (mTORC1) rather than calcineurin. mTORC1 integrates cytokine signals (IL-2, IL-15) to drive G1-to-S cell cycle progression; blockade prevents lymphocyte proliferation downstream of IL-2 signalling. Notable side effects: hyperlipidaemia, impaired wound healing, thrombocytopenia, pneumonitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Transplant Immunology','hard','mcq','C4d deposition in peritubular capillaries on a renal transplant biopsy is a specific marker for which form of rejection?','["A. Calcineurin inhibitor nephrotoxicity", "B. BK polyomavirus nephropathy", "C. Chronic calcineurin inhibitor toxicity causing tubular atrophy", "D. Antibody-mediated rejection (AMR) caused by donor-specific antibodies activating complement"]','D','C4d is a complement degradation product that covalently binds to peritubular capillary endothelium following complement activation by donor-specific antibodies engaging HLA antigens on graft endothelium. It is a stable footprint of AMR per the Banff classification. Diagnosis requires allograft dysfunction/histological injury, evidence of antibody-endothelium interaction (C4d or microvascular injury), and circulating DSA. Calcineurin toxicity causes arteriolar hyalinosis; BK virus requires SV40 large T antigen immunostaining.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Transplant Immunology','easy','mcq','Which form of GVHD presents with sicca syndrome, skin sclerosis resembling scleroderma, and bronchiolitis obliterans more than 100 days after HSCT?','["A. Acute GVHD (onset within 100 days)", "B. Chronic GVHD (onset after 100 days)", "C. Hyperacute GVHD (onset within 24 hours)", "D. Engraftment syndrome (peri-engraftment inflammatory response)"]','B','Chronic GVHD (cGVHD) occurs after 100 days and resembles autoimmune connective tissue diseases: lacrimal and salivary gland sicca syndrome, cutaneous sclerosis and fasciitis (scleroderma-like), bronchiolitis obliterans causing obstructive ventilatory defect, hepatic cholestasis, and musculoskeletal involvement. cGVHD is driven by chronic donor T cell activation against host stromal antigens and is a major cause of late non-relapse morbidity after allogeneic HSCT.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Tumour Immunology & Immunotherapy','easy','mcq','Tumour-specific antigens (TSAs) differ from tumour-associated antigens (TAAs). Which statement correctly distinguishes them?','["A. TSAs are expressed at low levels on normal cells; TAAs are completely absent from normal tissues", "B. TSAs arise uniquely in tumour cells (neoantigens, viral oncoproteins, cancer-testis antigens) while TAAs are overexpressed normal proteins", "C. TSAs are exclusively carbohydrate antigens; TAAs are exclusively protein antigens", "D. TSAs arise only from oncogenic viruses; TAAs arise only from somatic point mutations"]','B','TSAs are truly tumour-unique: neoantigens from somatic mutations, viral oncoproteins (HPV E6/E7, EBV LMP-1/2), and cancer-testis antigens (MAGE, NY-ESO-1) re-expressed aberrantly. TAAs are normal proteins overexpressed (HER2 in breast/gastric cancer, PSA in prostate) or developmental proteins re-expressed (AFP in HCC, CEA in colorectal). TSAs are the preferred targets for T cell and vaccine-based immunotherapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Tumour Immunology & Immunotherapy','medium','mcq','PD-L1 on tumour cells binds PD-1 on T cells. What is the functional consequence for tumour-infiltrating CTLs?','["A. Activation and clonal expansion of CTLs within the tumour", "B. NK cell activation and enhanced perforin-mediated tumour killing", "C. T cell exhaustion and functional anergy allowing tumour immune escape", "D. Upregulation of MHC class I on tumour cells improving CTL recognition"]','C','PD-1 on T cells, when engaged by PD-L1 on tumour cells (often induced by IFN-gamma), recruits SHP-1 and SHP-2 phosphatases that dephosphorylate key TCR and CD28 signalling molecules, causing T cell exhaustion: reduced IFN-gamma secretion, impaired proliferation, and eventual apoptosis. Tumour IFN-gamma drives PD-L1 expression in a negative feedback loop that tumours exploit for immune evasion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Tumour Immunology & Immunotherapy','medium','mcq','Pembrolizumab and nivolumab are approved for multiple solid tumours. What is their shared mechanism of action?','["A. Anti-CTLA-4 monoclonal antibodies preventing B7 co-stimulation at T cell priming", "B. Anti-CD20 monoclonal antibodies depleting regulatory B cells in tumour stroma", "C. Anti-VEGF antibodies normalising tumour vasculature", "D. Anti-PD-1 monoclonal antibodies blocking PD-1 and restoring T cell effector function in the tumour microenvironment"]','D','Pembrolizumab (Keytruda) and nivolumab (Opdivo) are anti-PD-1 monoclonal antibodies. By blocking the PD-1-PD-L1/PD-L2 interaction, they release the inhibitory checkpoint on exhausted tumour-infiltrating T cells, restoring cytotoxic activity. Approved for melanoma, NSCLC, HNSCC, urothelial carcinoma, MSI-H tumours, HCC, and others. Anti-CTLA-4 is ipilimumab; anti-VEGF is bevacizumab.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Tumour Immunology & Immunotherapy','hard','mcq','Ipilimumab (anti-CTLA-4) causes immune-related adverse events. Why does CTLA-4 blockade cause systemic autoimmune-like toxicity?','["A. CTLA-4 blockade activates classical complement in normal tissues", "B. Treg cells constitutively express CTLA-4 for suppression; CTLA-4 blockade depletes intratumoral Tregs and releases peripheral immune tolerance in normal organs", "C. CTLA-4 blockade induces mast cell degranulation at mucosal surfaces", "D. CTLA-4 blockade prevents B7 binding to CD28 on normal tissue-resident T cells"]','B','CTLA-4 is expressed on activated effector T cells (co-inhibitory receptor) and Tregs (constitutively, as a critical suppressive mechanism). Anti-CTLA-4 (ipilimumab) enhances T cell priming and functionally depletes CTLA-4-high Tregs in tumours via ADCC by macrophages. Loss of Treg-mediated peripheral tolerance causes organ-specific irAEs: colitis (~20-30%), hepatitis, dermatitis, hypophysitis, thyroiditis. Management: high-dose corticosteroids.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Tumour Immunology & Immunotherapy','easy','mcq','CAR-T cell therapy targets tumour antigens. What key advantage does CAR-mediated antigen recognition have over conventional TCR recognition?','["A. CAR-T cells require MHC class I for optimal antigen detection", "B. CAR-T cells produce IL-4 to recruit eosinophils for tumour killing", "C. CARs recognise surface antigens directly without MHC restriction, bypassing tumour MHC class I downregulation", "D. CARs exclusively target intracellular neoantigens with higher specificity than TCRs"]','C','CARs combine an extracellular scFv antibody fragment (for antigen binding) with intracellular T cell signalling domains (CD3-zeta with CD28 or 4-1BB co-stimulatory domains). Because the recognition domain is antibody-derived, CARs bind surface antigens directly without MHC presentation, bypassing downregulated MHC class I. CD19-CAR-T cells (tisagenlecleucel, axicabtagene) are approved for B-ALL and DLBCL.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Tumour Immunology & Immunotherapy','medium','mcq','Which tumour antigen is expressed in testis and placenta normally but aberrantly re-expressed in melanoma and lung cancer, making it a vaccine target?','["A. HER2/neu (ErbB2) overexpressed in breast and gastric cancer", "B. Prostate-specific antigen (PSA)", "C. MAGE-A3 (melanoma-associated antigen A3)", "D. Alpha-fetoprotein (AFP) elevated in hepatocellular carcinoma"]','C','MAGE genes are cancer-testis antigens: normally expressed only in testis (immune-privileged, no MHC class I) and placenta, but aberrantly re-expressed in melanoma, NSCLC, bladder cancer, and others. Since T cells were never tolerised against MAGE proteins, they appear as TSAs. MAGE-A3 has been extensively studied as a cancer vaccine antigen. HER2, PSA, and AFP are overexpressed normal TAAs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Tumour Immunology & Immunotherapy','hard','mcq','The cancer immunoediting hypothesis proposes three phases of tumour-immune interaction. What specifically characterises the equilibrium phase?','["A. Complete immune elimination of all tumour cells restoring normal tissue architecture", "B. NK cell and complement-mediated lysis of the entire tumour mass before adaptive immunity is required", "C. Progressive tumour growth due to complete immune suppression and evasion", "D. Dynamic balance where immune pressure selects less immunogenic tumour variants while holding others in dormancy"]','D','Cancer immunoediting: (1) Elimination - immune cells destroy highly immunogenic tumour cells; (2) Equilibrium - immune pressure from CD8+ T cells and NK cells selects for less immunogenic variants (loss of neoantigens, reduced MHC I), while holding remaining tumour cells in dormancy - this may last years to decades; (3) Escape - immune-resistant clones with PD-L1 upregulation, Treg recruitment, and TGF-beta production grow progressively.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Tumour Immunology & Immunotherapy','medium','mcq','Tumours upregulating MHC class I to evade CTL killing paradoxically also escape NK cell killing. Which inhibitory mechanism explains this paradox?','["A. Upregulated MHC I is recognised as foreign by NK activating receptors triggering NK killing", "B. Upregulated MHC I blocks expression of NKG2D ligands (MICA/MICB) on the tumour surface", "C. Upregulated MHC I enables efficient cross-presentation to activate more CD8+ T cells", "D. Upregulated MHC I engages NK inhibitory receptors (KIRs and NKG2A/CD94), preventing NK cell activation"]','D','NK cells kill targets with reduced or absent MHC class I (missing-self). When tumours upregulate MHC class I (to re-present neoantigens or escape NK pressure), the increased MHC I engages NK inhibitory receptors - KIRs recognising specific HLA-C allotypes, and NKG2A/CD94 recognising HLA-E - preventing NK activation. This illustrates the competing immune pressures driving tumour evolution: downregulating MHC I evades CTLs but exposes tumours to NK cells, and vice versa.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Tumour Immunology & Immunotherapy','hard','mcq','Cytokine release syndrome (CRS) after CAR-T therapy can be life-threatening. Which cytokine is the principal mediator and is specifically targeted by tocilizumab?','["A. IL-6 from bystander macrophages activated by CAR-T cells", "B. IL-12 from activated dendritic cells in the bone marrow", "C. IFN-gamma secreted directly by the CAR-T cells", "D. TNF-alpha from tumour-associated macrophages"]','A','CRS occurs when CAR-T cells expand and kill target cells, activating bystander macrophages which produce massive quantities of IL-6, IL-1, IFN-gamma, and MCP-1/CCL2. IL-6 is the dominant mediator driving fever, hypotension, capillary leak, and multi-organ dysfunction. Tocilizumab (anti-IL-6R monoclonal antibody) is FDA-approved for treating severe CRS after CAR-T therapy. Anakinra (anti-IL-1R) is used for refractory CRS and ICANS.','universal',false,'{year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Immunology','Pathology','Tumour Immunology & Immunotherapy','easy','mcq','Tumour cells frequently downregulate MHC class I expression. What is the direct consequence for CD8+ CTL-mediated anti-tumour killing?','["A. CTLs cannot recognise tumour cells because TCR recognition requires peptide-MHC class I complexes on the target", "B. CTLs are more efficiently activated because hidden neoantigens become exposed on the tumour surface", "C. CTLs switch to antibody production against tumour-associated antigens", "D. CTLs upregulate perforin-2 expression to compensate for absent MHC class I"]','A','CD8+ CTL killing requires direct TCR binding to specific peptide-MHC class I complexes on target cells. When tumours lose or downregulate MHC class I (via beta-2-microglobulin mutations, TAP1/TAP2 loss, or epigenetic HLA silencing), CTLs cannot recognise or kill these cells. This is the most common mechanism of acquired resistance to anti-PD-1/PD-L1 checkpoint inhibitor therapy. NK cells compensate by killing MHC I-deficient tumour cells.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed')
